(()=>{const app=window.__CITY_APP,C=window.CITY;const S={"cx":3485.33,"cz":-2774.54,"tx":0.9997,"tz":0.0249,"nx":0.0249,"nz":-0.9997};
const fr=(x,z)=>({u:(x-S.cx)*S.tx+(z-S.cz)*S.tz,v:(x-S.cx)*S.nx+(z-S.cz)*S.nz});
// this curb's cycle track pieces within 90 m along
const pieces=C.CYCLING_BANDS.filter(b=>!b.cross&&b.kind===3&&b.P.some(p=>{const f=fr(p.x,p.z);return Math.abs(f.u)<90&&f.v<1&&f.v>-7;}));
const near=(x,z)=>{let best=null,bd=1e9;for(const b of pieces){const Q=b.P;for(let i=0;i+1<Q.length;i++){const a=Q[i],c=Q[i+1];const ex=c.x-a.x,ez=c.z-a.z,L2=ex*ex+ez*ez;if(L2<1e-6)continue;let t=((x-a.x)*ex+(z-a.z)*ez)/L2;t=Math.max(0,Math.min(1,t));const qx=a.x+ex*t,qz=a.z+ez*t,d=Math.hypot(qx-x,qz-z);if(d<bd){bd=d;const L=Math.sqrt(L2);best={qx,qz,tx:ex/L,tz:ez/L,nx:a.nx,nz:a.nz,sq:(a.sq||0)+((c.sq||0)-(a.sq||0))*t};}}}return best;};
// start 30 m before the platform the way the track runs
const d0=near(S.cx,S.cz);const dir=Math.sign(d0.tx*S.tx+d0.tz*S.tz)||1;
let q=near(S.cx-S.tx*dir*30-S.nx*3,S.cz-S.tz*dir*30-S.nz*3);const half=(1.85-q.sq)/2;
app.teleportTo(q.qx+q.nx*half,q.qz+q.nz*half,Math.atan2(q.tx,q.tz));app.cameraSystem.cinema=null;
const cm=app.controllerManager,bike=cm.entities.cyclist,c0=cm.worldContactCount||0,t0=performance.now();let minBarrier=99,minV=99,maxV=-99,log=[];
(function f(){const p=bike.position,r=near(p.x,p.z),h=(1.85-r.sq)/2;const ax=r.qx+r.tx*6+r.nx*h,az=r.qz+r.tz*6+r.nz*h;bike.heading=Math.atan2(ax-p.x,az-p.z);
 const g=fr(p.x,p.z);if(Math.abs(g.u)<4.1){minBarrier=Math.min(minBarrier,-g.v-0.9);}minV=Math.min(minV,g.v);maxV=Math.max(maxV,g.v);
 log.push([+g.u.toFixed(1),+g.v.toFixed(2),+bike.speed.toFixed(1),+r.sq.toFixed(2)]);
 if(performance.now()-t0<11000)setTimeout(f,100);else console.log('[ride] '+JSON.stringify({contacts:(cm.worldContactCount||0)-c0,minClearOfPlatformEdge:+minBarrier.toFixed(2),vRange:[+maxV.toFixed(2),+minV.toFixed(2)],samples:log.filter((_,i)=>i%5==0)}));})();})()
